import com.spinplayer.app.NetDownloader;
import org.schabi.newpipe.extractor.*;import org.schabi.newpipe.extractor.search.*;import org.schabi.newpipe.extractor.stream.*;
import java.util.*;import java.io.*;import java.net.*;
public class DownloadProbe {
 public static void main(String[] args)throws Exception{NewPipe.init(new NetDownloader());File dir=new File(args[0]);dir.mkdirs();for(String source:new String[]{"SoundCloud","YouTube"}){String phase="search";try{StreamingService service=NewPipe.getService(source);SearchInfo search=SearchInfo.getInfo(service,service.getSearchQHFactory().fromQuery("Creative Commons",Collections.emptyList(),""));if(search.getRelatedItems().isEmpty())throw new IOException("Empty search");System.out.println("SEARCH\t"+source);StreamInfoItem selected=null;for(InfoItem item:search.getRelatedItems())if(item instanceof StreamInfoItem){StreamInfoItem track=(StreamInfoItem)item;if(track.getDuration()>0&&track.getDuration()<=300){selected=track;break;}}if(selected==null)throw new IOException("No short test audio");phase="formats";StreamInfo info=StreamInfo.getInfo(selected.getUrl());AudioStream best=null;for(AudioStream stream:info.getAudioStreams())if(stream.isUrl()&&stream.getDeliveryMethod()==DeliveryMethod.PROGRESSIVE_HTTP&&stream.getFormat()!=null&&(best==null||stream.getAverageBitrate()>best.getAverageBitrate()))best=stream;if(best==null)throw new IOException("No progressive audio");System.out.println("FORMATS\t"+source);phase="download";File output=new File(dir,source+"."+best.getFormat().getSuffix());HttpURLConnection connection=NetDownloader.connect(best.getContent());try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(output)){if(connection.getResponseCode()!=200)throw new IOException("HTTP status "+connection.getResponseCode());long total=0;byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){total+=n;if(total>80*1024*1024)throw new IOException("Test file exceeds limit");out.write(bytes,0,n);}if(total<1024)throw new IOException("Empty or invalid payload");}finally{connection.disconnect();}System.out.println("DOWNLOADED\t"+source);phase="decode";Process decoder=new ProcessBuilder("ffmpeg","-nostdin","-v","error","-i",output.getAbsolutePath(),"-f","null","-").redirectError(ProcessBuilder.Redirect.INHERIT).start();if(decoder.waitFor()!=0)throw new IOException("Decode failed");System.out.println("DECODED\t"+source);}catch(Throwable error){System.out.println("FAILED\t"+source+"\t"+phase+"\t"+error.getClass().getSimpleName());}}}
}
